/**
 * Content OS — initial creative rule library (110 rules, 10 categories).
 *
 * Single source of truth for migration 1100 (generated by
 * `npm run rules:seed`). Rules are original wording. `evidence_type`:
 *   - established_principle : widely documented in psychology, rhetoric or
 *     narrative craft (the note names the principle; applying it to short
 *     video is still an inference, not a proven performance effect).
 *   - practitioner_heuristic: common creator/marketing practice; useful but
 *     not formally validated.
 *   - experimental          : plausible idea worth testing; treat with care.
 *
 * Adding rules later does NOT require code changes: workspaces create rules
 * in the UI and platform admins can add global rules through the same table.
 */
export type ScriptFormat =
  | "instagram_reel" | "educational" | "promotional" | "storytelling" | "talking_head"
  | "product_presentation" | "list_based" | "tutorial" | "opinion" | "narrative";
export type Objective = "awareness" | "educate" | "engage" | "trust" | "convert" | "community" | "entertain";
export type RuleCategory =
  | "attention_psychology" | "hooks_openings" | "storytelling" | "audience_retention" | "curiosity"
  | "emotional_connection" | "authority_credibility" | "persuasion" | "conversion" | "calls_to_action";
export type Evidence = "established_principle" | "practitioner_heuristic" | "experimental";
export type Complexity = "basic" | "intermediate" | "advanced";

export interface RuleSeed {
  slug: string;
  name: string;
  category: RuleCategory;
  description: string;
  objective: string;
  application_conditions: string[];
  avoidance_conditions: string[];
  example: string;
  recommended_formats: ScriptFormat[];
  objectives: Objective[];
  tones_excluded: string[];
  min_duration_seconds: number | null;
  max_duration_seconds: number | null;
  complexity_level: Complexity;
  evidence_type: Evidence;
  evidence_note: string | null;
  tags: string[];
}

const ALL: ScriptFormat[] = ["instagram_reel", "educational", "promotional", "storytelling", "talking_head", "product_presentation", "list_based", "tutorial", "opinion", "narrative"];
const SHORT: ScriptFormat[] = ["instagram_reel", "talking_head", "list_based", "opinion", "educational"];
const STORY: ScriptFormat[] = ["storytelling", "narrative", "instagram_reel", "talking_head"];
const TEACH: ScriptFormat[] = ["educational", "tutorial", "list_based", "talking_head"];
const SELL: ScriptFormat[] = ["promotional", "product_presentation", "instagram_reel"];

type Compact = {
  s: string; n: string; d: string; o: string; a: string[]; v?: string[]; x: string;
  f?: ScriptFormat[]; ob?: Objective[]; t?: string[]; min?: number; max?: number;
  c?: "b" | "i" | "a"; e: "est" | "prac" | "exp"; en?: string; g: string[];
};

const EV = { est: "established_principle", prac: "practitioner_heuristic", exp: "experimental" } as const;
const CX = { b: "basic", i: "intermediate", a: "advanced" } as const;

function build(category: RuleCategory, rules: Compact[]): RuleSeed[] {
  return rules.map((r) => ({
    slug: r.s,
    name: r.n,
    category,
    description: r.d,
    objective: r.o,
    application_conditions: r.a,
    avoidance_conditions: r.v ?? [],
    example: r.x,
    recommended_formats: r.f ?? ALL,
    objectives: r.ob ?? [],
    tones_excluded: r.t ?? [],
    min_duration_seconds: r.min ?? null,
    max_duration_seconds: r.max ?? null,
    complexity_level: CX[r.c ?? "b"],
    evidence_type: EV[r.e],
    evidence_note: r.en ?? null,
    tags: r.g,
  }));
}

